//! Cargo-driven `mf.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is mf-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", None),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", None),
        o => panic!("mf-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/win32/mf/mf_r.o", "body", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:uuid", "engine:c:mfuuid", "engine:c:strmiids", "engine:c:dxguid", "engine:oldnames", "import:evr", "import:urlmon", "import:user32", "import:advapi32", "import:mfplat", "import:ole32", "import:oleaut32", "import:shlwapi", "import:kernelbase", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:delayimp_rust"],
        "x86_64" => &["dll/win32/mf/mf_r.o", "body", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:uuid", "engine:c:mfuuid", "engine:c:strmiids", "engine:c:dxguid", "engine:oldnames", "import:evr", "import:urlmon", "import:user32", "import:advapi32", "import:mfplat", "import:ole32", "import:oleaut32", "import:shlwapi", "import:kernelbase", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:delayimp_rust"],
        "aarch64" => &["dll/win32/mf/mf_r.o", "body", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:uuid", "engine:c:mfuuid", "engine:c:strmiids", "engine:c:dxguid", "engine:oldnames", "import:evr", "import:urlmon", "import:user32", "import:advapi32", "import:mfplat", "import:ole32", "import:oleaut32", "import:shlwapi", "import:kernelbase", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/mf",
        "dll/win32/mf",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x0A00",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    // cmake built the body with these RUSTFLAGS (its rust_staticlib_variant ENV).
    let body_rustflags = match arch.as_str() {
        "x86" => Some("-C target-feature=+sse,+sse2"),
        _ => None,
    };
    let mut link = Linker::new(target_json);
    if let Some(flags) = body_rustflags {
        link = link.rust_build_rustflags(flags);
    }
    link
        .rust_staticlib("mf-rust")
        .rc("dll/win32/mf/mf.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/mf/mf.spec", "mf.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/evr/evr.spec", "evr.dll", "evr")
        .delay_import_lib("dll/win32/urlmon/urlmon.spec", "urlmon.dll", "urlmon")
        .delay_import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/mfplat/mfplat.spec", "mfplat.dll", "mfplat")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/kernelbase/kernelbase.spec", "kernelbase.dll", "kernelbase")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
